type Direction = 'previous' | 'next';

export function getCurrentSuggestion(
  container: HTMLDivElement | null,
  currentSuggestionId?: string,
) {
  if (!container || !currentSuggestionId) {
    return null;
  }

  return container.querySelector<HTMLLIElement>(
    `[data-strato-filter-field-suggestion-id="${currentSuggestionId}"]`,
  );
}

/**
 * Get the next suggestion in the given container element.
 * If direction is set to 'next', start at the first suggestion. Else, start at the last.
 * If a 'currentSuggestionId' is passed, start at the matching suggestion.
 */
export function getNextSuggestion(
  direction: Direction,
  container: HTMLDivElement | null,
  currentSuggestionId?: string,
): HTMLElement | null {
  if (!container) {
    return null;
  }

  let currentSuggestion: HTMLElement | null = null;

  // Get the suggestion with the given id.
  if (currentSuggestionId) {
    currentSuggestion = getCurrentSuggestion(container, currentSuggestionId);
  }

  // If no suggestion has been found, return the first suggestion or start searching
  // at the last child of the container, depending on the direction.
  if (!currentSuggestion) {
    switch (direction) {
      case 'next': {
        return container.querySelector<HTMLLIElement>(
          '[data-strato-filter-field-suggestion-id]',
        );
      }
      case 'previous': {
        currentSuggestion = container.lastElementChild as HTMLElement;
        break;
      }
    }
  }

  // Recursively look for the next suggestion (suggestion may be nested).
  return _getNextSuggestion(direction, currentSuggestion);
}

function _getNextSuggestion(
  direction: Direction,
  currentNode?: HTMLElement | null,
): HTMLElement | null {
  while (currentNode) {
    if (currentNode.childElementCount > 0) {
      currentNode = (
        direction === 'next'
          ? currentNode.firstElementChild
          : currentNode.lastElementChild
      ) as HTMLElement;

      if (
        currentNode &&
        currentNode.dataset.stratoFilterFieldSuggestionId !== undefined
      ) {
        return currentNode;
      }

      return _getNextSuggestion(direction, currentNode);
    }

    currentNode = _getNextSibling(direction, currentNode);

    if (currentNode?.dataset.stratoFilterFieldSuggestionId !== undefined) {
      return currentNode as HTMLElement;
    }
  }

  return null;
}

/**
 * Get the next sibling, going back up the DOM if no next / previous element sibling
 * exists until we are at the root of the suggestions overlay.
 */
function _getNextSibling(
  direction: Direction,
  currentNode?: HTMLElement | null,
): HTMLElement | undefined {
  if (currentNode?.classList.contains('suggestions-overlay')) {
    return undefined;
  }

  if (currentNode) {
    const _tmpNode =
      direction === 'next'
        ? currentNode.nextElementSibling
        : currentNode.previousElementSibling;

    if (!_tmpNode) {
      return _getNextSibling(direction, currentNode.parentElement);
    }

    return _tmpNode as HTMLElement;
  }
}
